import React, { createContext, Dispatch, SetStateAction } from 'react';

export type NavItemsContextProps = {
  /** Whether the NavItems slot is used in the AppHeader. */
  hasNavItems: boolean;
  /** Whether the navItems are overflowing (at least one item doesn't fit in the container). */
  isNavOverflowing: boolean;
  /** Function to update the isNavOverflowing context value. */
  setIsNavOverflowing: Dispatch<SetStateAction<boolean>>;
};

/**
 * Navigation items context, used to access the overflowing/expanded state of the items in other components.
 */
export const NavItemsContext: React.Context<NavItemsContextProps> =
  createContext<NavItemsContextProps>({
    hasNavItems: false,
    isNavOverflowing: false,
    setIsNavOverflowing: () => false,
  });
